bounded_host_request.command:
set -eu
r=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
w="$r/.worktrees/room-live-2467fe6"
echo TARGET_REPO=$(git -C "$r" remote get-url origin | sed -E 's#(https://)[^/]*@#\1#')
echo ROOT_HEAD=$(git -C "$r" rev-parse HEAD)
echo WORKTREE_HEAD=$(git -C "$w" rev-parse HEAD)
echo USERBOT_SERVICE_ACTIVE=$(systemctl --user is-active gace-userbot-verify.service || :)
echo USERBOT_SERVICE_ENABLED=$(systemctl --user is-enabled gace-userbot-verify.service || :)
pid=$(systemctl --user show gace-userbot-verify.service -p MainPID --value)
echo USERBOT_PID_IS_LIVE=$([ "$pid" != 0 ] && [ -n "$pid" ] && test -d "/proc/$pid" && echo YES || echo NO)
echo USERBOT_START_TIMESTAMP=$(systemctl --user show gace-userbot-verify.service -p ExecMainStartTimestamp --value)
for p in "$r/scripts/userbot_keepalive.py" "$r/scripts/userbot_resident_ipc.py" "$r/scripts/userbot_test_client.py" "$w/scripts/userbot_keepalive.py" "$w/scripts/userbot_resident_ipc.py" "$w/scripts/userbot_test_client.py"; do if test -f "$p"; then echo SCRIPT_$(basename "$p")_$(test "$p" = "$r/"* && echo ROOT || echo WORKTREE)=PRESENT; else echo SCRIPT_$(basename "$p")_$(test "$p" = "$r/"* && echo ROOT || echo WORKTREE)=ABSENT; fi; done
for p in "$r/deploy/secrets/userbot_verify.sock" "$w/deploy/secrets/userbot_verify.sock"; do if test -S "$p"; then echo IPC_SOCKET_$(test "$p" = "$r/"* && echo ROOT || echo WORKTREE)=PRESENT; else echo IPC_SOCKET_$(test "$p" = "$r/"* && echo ROOT || echo WORKTREE)=MISSING; fi; done
echo SESSION_PRESENT=$([ -f "$r/deploy/secrets/userbot_verify.session" ] && echo YES || echo NO)
echo SESSION_SAFE_MODE=$([ -f "$r/deploy/secrets/userbot_verify.session" ] && test "$(stat -c %a "$r/deploy/secrets/userbot_verify.session")" = 600 && echo YES || echo NO)
echo UNIT_EXEC_PATH=$(systemctl --user cat gace-userbot-verify.service | grep '^ExecStart=' | sed -E 's#^.*python -u ([^ ]+).*#\1#' | head -1)
echo USERBOT_CONNECTED_LOG_SEEN=$(journalctl --user -u gace-userbot-verify.service --since '2 days ago' --no-pager -o cat 2>/dev/null | grep -q '^USERBOT_SESSION_CONNECTED' && echo YES || echo NO)
echo READONLY_IPC_DIAG_PASS
